const e = $json;
const system = SYSTEM_PROMPT.replace(/\{\{(\w+)\}\}/g, (m, key) => (key in CONFIG ? CONFIG[key] : m));

// The email goes in the user turn, fenced in tags. Remove look-alike tags so the sender can't close the fence.
const clean = (s) => String(s || '').replace(/<\/?\s*(email|from|subject|received_at|source|body)\s*>/gi, '');
const user = [
  '<email>',
  `<source>${e.source}</source>`,
  `<from>${clean(e.from_name)} <${clean(e.from_address)}></from>`,
  `<subject>${clean(e.subject)}</subject>`,
  `<received_at>${e.received_at}</received_at>`,
  '<body>',
  clean(e.text),
  '</body>',
  '</email>',
  '',
  'Score this message, summarise it for the founder, and draft a reply if it is an A or B.',
].join('\n');

const format = { type: 'json_schema', schema: OUTPUT_SCHEMA };

return {
  json: {
    ...e,
    // True while the Brand Bible / Sales Workflow slots in the prompt are still unfilled.
    prompt_incomplete: system.includes('⟦') || Object.values(CONFIG).some((v) => v.includes('REPLACE_ME')),
    haiku_body: {
      model: 'claude-haiku-5-5',
      max_tokens: 16000,
      system,
      output_config: { effort: 'low', format },
      messages: [{ role: 'user', content: user }],
    },
    opus_body: {
      model: 'claude-opus-5-5',
      max_tokens: 16000,
      system,
      output_config: { effort: 'medium', format },
      // If Opus declines on safety grounds, the API re-runs the request on its recommended fallback model.
      // Needs the header  anthropic-beta: server-side-fallback-2026-07-01  on the Opus HTTP node.
      fallbacks: 'default',
      messages: [{ role: 'user', content: user }],
    },
  },
};
